import {buildings} from './data.mjs';
let lastKey=null,lastView='find',language=false,focusedBuilding=null,queuedFrame=null,animateNext=false,threadMotion=null,paperMotion=null;
const motions=new WeakMap(),$=s=>document.querySelector(s),reduced=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function animatePaper(){paperMotion?.cancel();if(reduced())return;const file=$('.case-file');if(file)paperMotion=file.animate([{opacity:0,transform:matchMedia('(max-width:800px)').matches?'translateY(18px) rotate(-1deg)':'translateX(22px) rotate(1.5deg)'},{opacity:1,transform:'translate(0) rotate(0)'}],{duration:460,delay:110,easing:'cubic-bezier(.2,.75,.25,1)',fill:'backwards'});}
function queueLink(animate=false){animateNext=animateNext||animate;if(queuedFrame!==null)return;queuedFrame=requestAnimationFrame(()=>{queuedFrame=null;drawLink();});}
function drawLink(){const work=$('.case-workspace'),canvas=$('#branchLinkCanvas'),terminal=$('#branchTerminal'),map=$('#campusMap');if(!work||!canvas||!terminal||!map)return;
 const active=!!focusedBuilding&&!$('#boardPage').hidden,main=$('#branchLink'),shadow=$('#branchLinkShadow'),ring=$('#branchStart'),end=$('#branchEnd'),stem=$('#branchFloorLink');canvas.classList.toggle('has-link',active);
 if(!active){main.setAttribute('d','');shadow.setAttribute('d','');stem.setAttribute('d','');animateNext=false;return;}
 const pin=map.querySelector(`[data-building="${focusedBuilding.id}"]`),matrix=pin?.getScreenCTM();if(!matrix)return;
 const source=new DOMPoint(0,0).matrixTransform(matrix),wr=work.getBoundingClientRect(),tr=terminal.getBoundingClientRect(),ox=wr.left+work.clientLeft,oy=wr.top+work.clientTop;
 canvas.setAttribute('viewBox',`0 0 ${work.clientWidth} ${work.clientHeight}`);
 const sx=source.x-ox,sy=source.y-oy,ex=tr.x+tr.width/2-ox,ey=tr.y+tr.height/2-oy,mobile=matchMedia('(max-width:800px)').matches;
 const d=mobile?`M${sx} ${sy} C${sx+45} ${sy+75} ${ex-35} ${ey-65} ${ex} ${ey}`:`M${sx} ${sy} C${sx+65} ${sy-32} ${ex-85} ${ey+40} ${ex} ${ey}`;
 main.setAttribute('d',d);shadow.setAttribute('d',d);ring.setAttribute('cx',sx);ring.setAttribute('cy',sy);end.setAttribute('cx',ex);end.setAttribute('cy',ey);
 const floor=$('#indoorMap');if(floor&&!floor.hidden){const fr=floor.getBoundingClientRect(),fx=fr.left+23-ox,fy=fr.top+20-oy;stem.setAttribute('d',`M${ex} ${ey} C${ex+30} ${ey+50} ${fx-30} ${fy-50} ${fx} ${fy}`);}else stem.setAttribute('d','');
 if(animateNext&&!reduced()){threadMotion?.cancel();const length=main.getTotalLength();threadMotion=main.animate([{strokeDasharray:`${length} ${length}`,strokeDashoffset:length},{strokeDasharray:`${length} ${length}`,strokeDashoffset:0}],{duration:650,easing:'cubic-bezier(.2,.65,.3,1)'});ring.animate([{r:7,opacity:.3},{r:18,opacity:1},{r:13,opacity:1}],{duration:650});}animateNext=false;
}
function settleLink(){queueLink(true);let start=performance.now();function tick(now){queueLink();if(now-start<650)requestAnimationFrame(tick);}if(!reduced())requestAnimationFrame(tick);}
export function showExplorerList(){animatePaper();queueLink();}
export function setupExplorer({en,onPeriod,onReset}){
 language=en;const t=(zh,eng)=>en?eng:zh,work=$('.case-workspace');$('#boardPage').classList.add('unified-explorer','branch-board');document.body.classList.add('clue-explorer-enabled');
 const toolbar=document.createElement('div');toolbar.className='explorer-toolbar';toolbar.innerHTML=`<div class="explorer-search-row"><div id="sharedSearchSlot"></div><div id="sharedOriginSlot"></div></div><div class="explorer-view-row"><div class="explorer-switch" role="group" aria-label="${t('线索板操作','Caseboard controls')}"><button id="exploreList">${t('热门线索','Trending clues')}</button><button id="exploreMap">${t('地图总览','Map overview')}</button></div><label id="periodLabel">${t('回看','Look back')}<select id="popularPeriod" aria-label="${t('热门时间范围','Trending time period')}"><option value="7">${t('近7天','Last 7 days')}</option><option value="30">${t('近30天','Last 30 days')}</option></select></label><span id="explorerContext"></span><button id="explorerReset" class="text-button" hidden>← ${t('返回探索','Back to explore')}</button></div><div id="sharedFilterSlot"></div>`;
 work.prepend(toolbar);$('#sharedSearchSlot').append($('#searchForm'));$('#sharedOriginSlot').append($('.origin-row'));$('#sharedFilterSlot').append($('.categories'),$('#filters'));
 const layout=document.createElement('div');layout.className='branch-layout';const mapBoard=$('.evidence-board'),file=$('.case-file'),indoor=$('#indoorMap'),column=document.createElement('div');column.className='clue-extension-column';column.innerHTML=`<div class="branch-heading"><span id="branchTerminal" class="branch-terminal" aria-hidden="true"></span><span class="branch-kicker" id="branchKicker">THE CLUE COLLECTION</span><strong id="branchTitle"></strong><small id="branchSubtitle"></small></div>`;work.append(layout);layout.append(mapBoard,column,indoor);column.append(file);
 const hint=document.createElement('div');hint.id='mapClickHint';hint.className='map-click-hint';hint.textContent=t('点选建筑，红线会把它连到旁边的新线索；地图始终保留。','Pick a building. Follow its red thread to a new clue. The map stays in view.');mapBoard.prepend(hint);
 const memo=$('.map-memo');memo.classList.add('off-map-note');const notes=document.createElement('div');notes.className='map-annotation-strip';notes.append(memo);mapBoard.append(notes);
 const canvas=document.createElementNS('http://www.w3.org/2000/svg','svg');canvas.id='branchLinkCanvas';canvas.setAttribute('class','branch-link-canvas');canvas.setAttribute('aria-hidden','true');canvas.innerHTML='<path id="branchLinkShadow"/><path id="branchLink"/><path id="branchFloorLink"/><circle id="branchStart" r="13"/><circle id="branchEnd" r="5"/>';work.append(canvas);
 $('#exploreList').onclick=()=>{if(lastView==='saved'&&!$('#boardPage').classList.contains('has-case'))showExplorerList();else onReset();};$('#exploreMap').onclick=()=>{$('#resetMap').click();if(!reduced())map.animate([{opacity:.65},{opacity:1}],{duration:300});queueLink();};$('#popularPeriod').onchange=e=>{onPeriod(e.target.value);showExplorerList();};$('#explorerReset').onclick=onReset;
 $('#search').addEventListener('input',()=>queueLink());$('#searchForm').addEventListener('submit',showExplorerList);document.querySelectorAll('[data-category]').forEach(b=>b.addEventListener('click',showExplorerList));
 $('#indoorTab').textContent=t('楼层线索','Floor clue');$('#outdoorTab').textContent=t('校园地图','Campus map');
 window.addEventListener('resize',()=>queueLink());const map=$('#campusMap');new MutationObserver(()=>queueLink()).observe(map,{attributes:true,attributeFilter:['viewBox']});new MutationObserver(()=>queueLink()).observe(indoor,{attributes:true,attributeFilter:['hidden'],childList:true});if(window.ResizeObserver){const ro=new ResizeObserver(()=>queueLink());[work,file,map,indoor].forEach(node=>ro.observe(node));}
}
export function refreshExplorer({en,view,place,guide,stage,period,popular,query,category}){
 language=en;lastView=view;const t=(zh,eng)=>en?eng:zh,b=place?buildings.find(b=>b.id===place.building):buildings.find(b=>b.id.toLowerCase()===query.trim().toLowerCase()),key=view+'/'+(place?.id||'')+'/'+(guide?stage:'')+'/'+(b?.id||'');
 const changed=key!==lastKey;focusedBuilding=b||null;lastKey=key;const work=$('.case-workspace');work.dataset.explorerSelected=place?'true':'false';work.dataset.explorerView=view;work.dataset.guideStage=guide?String(stage):'';work.dataset.branchActive=b?'true':'false';work.dataset.explorerPanel=place?'detail':'list';
 $('#periodLabel').hidden=!popular||!!place;$('#popularPeriod').value=period;$('.explorer-search-row').hidden=!!place;$('#sharedFilterSlot').hidden=!!place;$('#explorerReset').hidden=!place;
 $('#explorerContext').textContent=place?(en?place.name:place.zh):view==='saved'?t('留给下一次的线索','Clues kept for next time'):popular?t('热度为演示数据','Illustrative popularity'):query?t('地图旁展开匹配线索','Matching clues beside the map'):category==='toilet'?t('按参考位置查找设施','Facilities around the reference origin'):t('地图与线索并排展开','Map and clues, side by side');
 $('#exploreList').textContent=view==='saved'&&!place?t('收藏线索','Saved clues'):t('热门线索','Trending clues');$('#exploreList').classList.toggle('is-return',!!place||!!query);$('#results').classList.toggle('popular-results',popular);$('#boardPage').classList.remove('mobile-map-open');
 $('#branchKicker').textContent=b?(guide?'FOLLOW THE THREAD':'A NEW LEAD'):view==='saved'?'THE FILED COLLECTION':'THE CLUE COLLECTION';$('#branchTitle').textContent=b?(en?b.name:b.zh):view==='saved'?t('留好的线索','Kept for next time'):t('从这里开始找','A little place to start');$('#branchSubtitle').textContent=b?(place?t('建筑已选定 · 地点档案在此展开','Building selected · place file unfolds here'):t('选择这栋楼里的具体地点','Choose a specific place in this building')):t('完整地图在旁，线索各有位置。','Every clue has its place. The map keeps its own.');
 document.querySelectorAll('.map-pin').forEach(pin=>{const active=pin.dataset.building===b?.id;pin.classList.toggle('branch-focused',active);pin.setAttribute('aria-pressed',String(active));});$('#threadLegend').textContent=t('红线关联线索，不是步行路线','Red thread connects clues, not walking directions');if(changed){if(!guide)animatePaper();settleLink();}else queueLink();
}
export function traceSelection({building}){focusedBuilding=building;animateNext=true;}
export function stopMapTween(svg){const frame=motions.get(svg);if(frame)cancelAnimationFrame(frame);motions.delete(svg);}
export function tweenMap(svg,target,commit){stopMapTween(svg);if(reduced()){commit(target);queueLink();return;}const from=svg.getAttribute('viewBox').split(/\s+/).map(Number),start=performance.now();function tick(now){const p=Math.min(1,(now-start)/500),e=1-(1-p)**3;commit(from.map((v,i)=>v+(target[i]-v)*e));queueLink();if(p<1)motions.set(svg,requestAnimationFrame(tick));else motions.delete(svg);}motions.set(svg,requestAnimationFrame(tick));}
export function animateMapStage(inside){const node=inside?$('#indoorMap'):$('#outdoorMap');if(!reduced())node.animate([{opacity:.15,transform:inside?'translateY(18px) rotate(-.5deg)':'translateY(0)'},{opacity:1,transform:'translateY(0) rotate(0)'}],{duration:480,easing:'cubic-bezier(.2,.7,.3,1)'});settleLink();}
